import { describe, it, expect, beforeAll, afterAll, beforeEach, vi } from 'vitest'
import type { Server } from 'node:http'
import type { AddressInfo } from 'node:net'

interface TodoRow {
  id: string
  userId: string
  title: string
  description: string | null
  priority: number
  dueDate: Date | null
  completed: boolean
  createdAt: Date
  updatedAt: Date
}

type Where = Partial<Pick<TodoRow, 'id' | 'userId' | 'completed' | 'priority'>>

interface OrderByItem {
  completed?: 'asc' | 'desc'
  dueDate?: { sort: 'asc' | 'desc'; nulls?: 'first' | 'last' }
}

// 실제 DB 없이 서비스 계층의 where/orderBy 계약을 검증하기 위한 인메모리 Prisma 스텁.
// orderBy로 전달된 정렬 조건을 해석해 서비스가 요청한 정렬이 응답에도 반영되게 한다.
const db = vi.hoisted(() => {
  let seq = 0
  const rows: TodoRow[] = []

  const matches = (row: TodoRow, where: Where) =>
    Object.entries(where).every(([key, value]) => {
      if (value === undefined) return true
      return row[key as keyof TodoRow] === value
    })

  const applyOrderBy = (list: TodoRow[], orderBy?: OrderByItem[]) => {
    if (!orderBy) return list
    return [...list].sort((a, b) => {
      for (const item of orderBy) {
        if (item.completed) {
          if (a.completed !== b.completed) {
            const diff = Number(a.completed) - Number(b.completed)
            return item.completed === 'asc' ? diff : -diff
          }
          continue
        }
        if (item.dueDate) {
          const aTime = a.dueDate ? a.dueDate.getTime() : null
          const bTime = b.dueDate ? b.dueDate.getTime() : null
          if (aTime === null && bTime === null) continue
          if (aTime === null) return item.dueDate.nulls === 'first' ? -1 : 1
          if (bTime === null) return item.dueDate.nulls === 'first' ? 1 : -1
          if (aTime !== bTime) return item.dueDate.sort === 'asc' ? aTime - bTime : bTime - aTime
        }
      }
      return 0
    })
  }

  return {
    rows,
    reset() {
      rows.length = 0
      seq = 0
    },
    create(data: Omit<TodoRow, 'id' | 'createdAt' | 'updatedAt'>) {
      const now = new Date()
      const row: TodoRow = { id: `todo-${++seq}`, createdAt: now, updatedAt: now, ...data }
      rows.push(row)
      return row
    },
    findMany(where: Where, orderBy?: OrderByItem[]) {
      return applyOrderBy(rows.filter((r) => matches(r, where)), orderBy)
    },
    findFirst(where: Where) {
      return rows.find((r) => matches(r, where)) ?? null
    },
    update(id: string, data: Partial<TodoRow>) {
      const row = rows.find((r) => r.id === id)
      if (!row) throw new Error('Record not found')
      Object.assign(row, data, { updatedAt: new Date() })
      return row
    },
    remove(id: string) {
      const idx = rows.findIndex((r) => r.id === id)
      if (idx < 0) throw new Error('Record not found')
      return rows.splice(idx, 1)[0]
    },
  }
})

