import { createApp } from '@/app'
import { MemorySessionStore } from '@/sessions/memory'
import { prisma } from '@/lib/prisma'

let server: Server
let base: string
const store = new MemorySessionStore()

const USER1 = { sid: 'sid-1', csrf: 'csrf-1' }
const USER2 = { sid: 'sid-2', csrf: 'csrf-2' }

interface ReqOptions {
  method?: string
  body?: unknown
  sid?: string
  csrf?: string
}

function api(path = '', init: ReqOptions = {}) {
  const headers: Record<string, string> = { 'Content-Type': 'application/json' }
  if (init.sid) headers.Cookie = `sid=${init.sid}`
  if (init.csrf) headers['X-CSRF-Token'] = init.csrf
  return fetch(`${base}/api/todos${path}`, {
    method: init.method ?? 'GET',
    headers,
    body: init.body !== undefined ? JSON.stringify(init.body) : undefined,
  })
}

const post = (body: unknown, user = USER1) =>
  api('', { method: 'POST', body, sid: user.sid, csrf: user.csrf })

interface TodoJson {
  id: string
  userId: string
  title: string
  description: string | null
  priority: number
  dueDate: string | null
  completed: boolean
}

beforeAll(async () => {
  const app = createApp(store)
  server = app.listen(0)
  await new Promise<void>((resolve) => server.once('listening', resolve))
  const { port } = server.address() as AddressInfo
  base = `http://127.0.0.1:${port}`

  const now = Date.now()
  await store.set(USER1.sid, { userId: 'user-1', csrfToken: USER1.csrf, createdAt: now, lastAccess: now }, 3600)
  await store.set(USER2.sid, { userId: 'user-2', csrfToken: USER2.csrf, createdAt: now, lastAccess: now }, 3600)
})

afterAll(async () => {
  await new Promise<void>((resolve, reject) =>
    server.close((err) => (err ? reject(err) : resolve())),
  )
})

